def collect_pages(pages):
    names = []
    page = 1
    for _ in range(3):
        response = pages.get(page)
        if not isinstance(response, dict) or not isinstance(response.get('items'), list):
            raise ValueError('invalid page')
        names.extend(response['items'])
        next_page = response.get('next')
        if next_page is None:
            return names
        if next_page not in (1, 2) or next_page == page:
            raise ValueError('invalid next page')
        page = next_page
    raise RuntimeError('page limit reached')

pages = {1: {'items': ['Python'], 'next': 2}, 2: {'items': ['SQL'], 'next': None}}
assert collect_pages(pages) == ['Python', 'SQL']
try:
    collect_pages({1: {'items': ['Python'], 'next': 2}})
except ValueError as error:
    assert str(error) == 'invalid page'
print(collect_pages(pages))
